function addDigitLists(a: ListNode | null, b: ListNode | null): ListNode | null {
  const read = (h: ListNode | null): bigint => {
    let s = "";
    for (; h; h = h.next) s = h.val + s; // ones digit first, so prepend
    return BigInt(s);
  };
  const digits = (read(a) + read(b)).toString();
  let out: ListNode | null = null;
  for (const ch of digits) out = new ListNode(Number(ch), out);
  return out;
}

